int head[MAXN], nxt[2*MAXM], to[2*MAXM], ecnt;
int dist[MAXN];
int queue[MAXN];
int signpost[MAXN];

void add_edge(int u, int v) {
    ecnt++;
    to[ecnt] = v;
    nxt[ecnt] = head[u];
    head[u] = ecnt;
}

int main() {
    int N, M;
    scanf("%d %d", &N, &M);

    memset(head, 0, sizeof(head));
    ecnt = 0;

    for (int i = 0; i < M; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
        add_edge(v, u);
    }

    memset(dist, 0x3f, sizeof(dist));
    dist[1] = 0;

    int front = 0, back = 0;
    queue[back++] = 1;

    while (front < back) {
        int u = queue[front++];
        for (int e = head[u]; e; e = nxt[e]) {
            int v = to[e];
            if (dist[v] == INF) {
                dist[v] = dist[u] + 1;
                queue[back++] = v;
            }
        }
    }

    // Check if all rooms can reach Room 1
    for (int i = 1; i <= N; i++) {
        if (dist[i] == INF) {
            printf("No\n");
            return 0;
        }
    }

    // Assign signposts
    memset(signpost, 0, sizeof(signpost));
    for (int v = 2; v <= N; v++) {
        // Find neighbor with dist = dist[v] - 1
        for (int e = head[v]; e; e = nxt[e]) {
            int u = to[e];
            if (dist[u] == dist[v] - 1) {
                signpost[v] = u;
                break;
            }
        }
