typedef struct {
    int to, next;
} Edge;

typedef struct {
    int v, d;
} Node;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    int *head = (int *)malloc((N + 1) * sizeof(int));
    Edge *edges = (Edge *)malloc((2 * M) * sizeof(Edge));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    int *ans = (int *)calloc(N + 1, sizeof(int));
    int *dist = (int *)malloc((N + 1) * sizeof(int));
    int *q = (int *)malloc((N + 5) * sizeof(int));

    if (!head || !edges || !deg || !ans || !dist || !q) return 0;

    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < M; i++) {
        int a, b;
        scanf("%d %d", &a, &b);

        edges[ecnt].to = b;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;
        deg[a]++;

        edges[ecnt].to = a;
        edges[ecnt].next = head[b];
        head[b] = ecnt++;
        deg[b]++;
    }

    const int INF = 1e9;
    for (int i = 1; i <= N; i++) dist[i] = INF;

    int front = 0, back = 0;
    q[back++] = 1;
    dist[1] = 0;

    while (front < back) {
        int u = q[front++];
        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            if (dist[v] == INF) {
                dist[v] = dist[u] + 1;
                q[back++] = v;
            }
        }
    }

    for (int v = 2; v <= N; v++) {
        if (dist[v] == INF) {
            printf("NO\n");
            free(head); free(edges); free(deg); free(ans); free(dist); free(q);
            return 0;
        }

        int cnt = 0, chosen = -1;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int u = edges[e].to;
            if (dist[u] == dist[v] - 1) {
                cnt++;
                chosen = u;
            }
        }

        if (cnt != 1) {
            printf("NO\n");
            free(head); free(edges); free(deg); free(ans); free(dist); free(q);
            return 0;
        }
        ans[v] = chosen;
    }

    printf("YES\n");
    for (int i = 2; i <= N; i++) {
        printf("%d %d\n", i, ans[i]);
    }

    free(head);
    free(edges);
    free(deg);
    free(ans);
    free(dist);
    free(q);
    return 0;
}

