/*
We need to decide whether we can assign, for every room i != 1, exactly one outgoing signpost
to some adjacent room so that following signposts from any room reaches room 1
and each signpost goes to a room whose distance to room 1 is exactly one less
(i.e. along a shortest path).

This is possible iff every room is reachable from room 1.
Then we can run BFS from room 1 to compute shortest distances and choose for each room i != 1
any adjacent room with distance dist[i] - 1.

Input assumed:
N M
u1 v1
...
uM vM

Output:
If impossible, print "No"
Otherwise print "Yes" and then for rooms 2..N print one chosen neighbor per line.

This matches the standard interpretation of the task.
*/
public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N, M;
        try {
            N = fs.nextInt();
        } catch (Exception e) {
            return;
        }
        M = fs.nextInt();

        List<Integer>[] g = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < M; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            g[u].add(v);
            g[v].add(u);
        }

        int[] dist = new int[N + 1];
        Arrays.fill(dist, -1);
        int[] parent = new int[N + 1];

        ArrayDeque<Integer> q = new ArrayDeque<>();
        dist[1] = 0;
        q.add(1);

        while (!q.isEmpty()) {
            int u = q.poll();
            for (int v : g[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    parent[v] = u;
                    q.add(v);
                }
            }
        }

        for (int i = 1; i <= N; i++) {
            if (dist[i] == -1) {
                System.out.println("No");
                return;
            }
        }

        StringBuilder sb = new StringBuilder();
        sb.append("Yes\n");
        for (int i = 2; i <= N; i++) {
            sb.append(parent[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}

